use std::io::{self,BufRead,Write};
fn main(){let mut out=io::stdout().lock();for line in io::stdin().lock().lines(){let line=line.unwrap();let mut s=line.split_whitespace();let op=s.next().unwrap();let n:usize=s.next().unwrap().parse().unwrap();let p:usize=s.next().unwrap().parse().unwrap();let a:usize=s.next().unwrap().parse().unwrap();let v:Vec<f64>=s.map(|x|x.parse().unwrap()).collect();assert_eq!(v.len(),n*p+a);let data=v[..n*p].chunks_exact(p).map(|r|r.to_vec()).collect::<Vec<_>>();let result=spatial::run(op,&data,&v[n*p..]).unwrap_or_else(|_|"null".into());writeln!(out,"{result}").unwrap();out.flush().unwrap();}}
